    public MediaPlayerShowcaseView()
    {
        InitializeComponent();

        DataContextChanged += (_, _) =>
        {
            if (DataContext is MediaPlayerShowcaseViewModel vm)
            {
                var player = _mediaPlayerControl;
                if (player is null) return;

                vm.PlayRequested += () => player.Play();
                vm.PauseRequested += () => player.Pause();
                vm.StopRequested += () => player.Stop();
                vm.SeekRequested += (pos) => player.Seek(pos);
                vm.VolumeChangedRequested += (vol) => player.Volume = vol / 100.0;
                vm.ToggleFullscreenRequested += () =>
                {
                    if (VisualRoot is Window window)
                    {
                        window.WindowState = window.WindowState == WindowState.FullScreen
                            ? WindowState.Normal
                            : WindowState.FullScreen;
                    }
                };

                // 當核心播放器內部狀態變更時，反向同步 ViewModel
                player.StateChanged += (_, state) =>
                {
                    if (state == MediaState.Playing && !vm.IsPlaying)
                    {
                        _ = vm.PlayCommand.ExecuteAsync(null);
                    }
                    else if (state == MediaState.Paused && vm.IsPlaying)
                    {
                        _ = vm.PauseCommand.ExecuteAsync(null);
                    }
                    else if (state == MediaState.Stopped && vm.IsPlaying)
                    {
                        _ = vm.StopCommand.ExecuteAsync(null);
                    }
                };

                // 初始化播放狀態
                if (player.AutoPlay && vm.IsPlaying)
                {
                    player.Play();
                }
            }
        };
    }

